    data class Contract(val valid: Boolean, val reason: String = "")

    /** Validate the live program using its stable cart semantics before any edit. */
    fun contract(bytes: ByteArray): Contract {
        if (bytes.size < 4 || bytes[0] != '\''.code.toByte()) return Contract(false, "not-source")
        val source = bytes.toString(Charsets.UTF_8)
        if (!source.startsWith("'use meta:release app-id=455578,")) return Contract(false, "wrong-app")
        val required = listOf("cartSubmitBar", "mainCard", "cartInstanceId", "saveInstanceState",
            "globalThis.weex", "CartAbility")
        val missing = required.firstOrNull { it !in source }
        if (missing != null) return Contract(false, "missing-semantic:$missing")
        val styleStart = source.indexOf(STYLE_START)
        val styleEnd = source.indexOf(STYLE_END, styleStart.coerceAtLeast(0))
        if (styleStart < 0 || styleEnd <= styleStart || source.indexOf(STYLE_START, styleStart + 1) >= 0)
            return Contract(false, "style-boundary")
        val footers = Regex("id:\\\"cartSubmitBar\\\"").findAll(source).count()
        if (footers != 1) return Contract(false, "footer-count:$footers")
        return Contract(true)
    }

    data class Geometry(
        val viewportWidth: Int,
        val barLeft: Int,
        val barRight: Int,
        val barTop: Int,
        val viewportBottom: Int,
        val buttonHeight: Int = 130,
        val buttonGap: Int = 0,
        val blurRadiusPx: Float = 8f,
    )

    fun decorate(source: ByteArray, geometry: Geometry): ByteArray? {
        if (geometry.viewportWidth <= 0 || geometry.barLeft < 0 ||
            geometry.barRight > geometry.viewportWidth || geometry.barLeft >= geometry.barRight ||
            geometry.barTop >= geometry.viewportBottom || geometry.barTop < 0 ||
            geometry.buttonHeight <= 0 || geometry.buttonGap < 0 ||
            !geometry.blurRadiusPx.isFinite() || geometry.blurRadiusPx !in 0f..128f) return null
        // Never reinterpret bytecode as source, or rewrite an unknown deployed bundle.
        val original = source.toString(Charsets.UTF_8)
        val contract = contract(source)
        if (!contract.valid || original.contains("liquidtab-cart-native-active")) return null
        val replacements = replacementsFor(original)
        if (replacements.isEmpty()) return null
        for ((marker, _) in replacements) {
            if (original.indexOf(marker) < 0 || original.indexOf(marker) != original.lastIndexOf(marker)) return null
        }
        // Each pair preserves the actual deployed callback body. Only the
        // surrounding visual wrapper and viewport extent are changed.
        var program = original
        for ((from, to) in replacements) program = program.replace(from, to)
        val start = program.indexOf(STYLE_START)
        val end = program.indexOf(STYLE_END, start.coerceAtLeast(0))
        if (start < 0 || end <= start || program[end - 1] != ',') return null
        val css = styles(geometry)
        // Extend the existing style array. Preserve the original bootstrap and all handlers.
        return (program.substring(0, end) + "[`$css`,0]," + program.substring(end))
            .toByteArray(Charsets.UTF_8)
    }

    private fun replacementsFor(source: String): List<Pair<String, String>> {
        if (FOOTER_CLASS !in source || LIST_HEIGHT !in source || MAIN_CLASS !in source ||
            CHECKBOX_ICON !in source || LEFT_CHILDREN !in source || SUBMIT_STYLE !in source ||
            SELECT_ALL_RETURN !in source || RIGHT_CLICK !in source || RIGHT_TOUCH !in source || CHECK_REF !in source) return emptyList()
        return listOf(LIST_HEIGHT to FULL_LIST_HEIGHT, MAIN_CLASS to SPLIT_MAIN_CLASS,
            FOOTER_CLASS to SPLIT_FOOTER_CLASS, CHECKBOX_ICON to HOLLOW_CHECKBOX_ICON,
            LEFT_CHILDREN to WRAPPED_LEFT_CHILDREN, APPEARANCE_BRIDGE to UPDATED_APPEARANCE_BRIDGE,
            SUBMIT_STYLE to NATIVE_SUBMIT_STYLE, SELECT_ALL_RETURN to UPDATED_SELECT_ALL_RETURN,
            RIGHT_CLICK to CAPTURED_RIGHT_CLICK, RIGHT_TOUCH to CAPTURED_RIGHT_TOUCH,
            CHECK_REF to UPDATED_CHECK_REF)
    }

